// ------------------------------------------------------------ sources (M2-01)
//
// ARCHITECTURE-SOURCES.md (dev branch) section 3 (state records, keys, validation,
// masking, Xtream, reducers) and UX-SOURCES.md (dev branch) 5.4-5.8 / 8.1 (codes,
// copy, view objects, form state) under the reconciliation rulings SR1-SR10:
// the state file keeps the architecture's field names (`key`, `url`,
// `epgUrl`, `lastUsed`, `fetchedAt`), the guide only ever sees `sourceView`
// objects with the UX names (`id`, `hasEpg`, `cachedAt`, `lastUsedAt`), the
// user-facing validation codes are the UX 5.4 list, every cap lives in
// LIMITS (SR5), and `maskUrl` keeps `type` / `output` readable (SR4).
// Nothing here logs, renders or touches I/O; no function ever returns a URL
// except `validateSourceUrl`, `xtreamUrls`, `sourceForEdit` and the state
// reducers, which the service alone consumes.

var CACHE_LAYOUT = 2
var MAX_SOURCES = 50
var MAX_SOURCE_URL = 2048
var MAX_LABEL = 64
var MAX_XTREAM_SERVER = 512
var MAX_XTREAM_FIELD = 256
var SOURCES_DIR = "sources"
var MASK = "****"
var MASK_CLEAR_PARAMS = ["type", "output"]
var LIMITS = { url: MAX_SOURCE_URL, label: MAX_LABEL, server: MAX_XTREAM_SERVER, user: MAX_XTREAM_FIELD, pass: MAX_XTREAM_FIELD, sources: MAX_SOURCES }
// The keys of the Sources screens, next to the hint table so the two cannot
// drift (UX-SOURCES 4.8). Guide.qml never spells a key.
// PAUSE LIVE TV. `c` for "cease", because p is picture-in-picture, s is stop
// and Space is preview -- the three keys a pause would naturally want are all
// taken by things a viewer also does often.
var PAUSE_KEY = "c"
// M3-02: the audio and subtitle picker. A bare letter, because the picker
// is list-mode only: search mode types it (PLAN-M3 section 2).
var TRACKS_KEY = "t"
// M4-02: the programme detail panel. `i` for information; d is unused but
// reads as "delete" beside x, and e is edit on Sources.
var DETAIL_KEY = "i"
// M5-01 live rewind (design 2.4): vim's letters, word back / word forward /
// go to the end, all three free in list mode and query text in search mode
// like `c`. The IPC verbs `back`, `forward` and `live` are the surface a
// watcher actually uses, because rewinding is done with the guide closed.
var REWIND_KEY = "b"
var FORWARD_KEY = "w"
var LIVE_KEY = "g"
// Step per guide press, one size, no setting (D7): the first rewindable
// second arrives about 6 s after a zap and the median window is 411 s, so
// 10 s reaches a missed sentence in one to three taps.
var REWIND_STEP_S = 10
// "Behind live" below this is shown as live. The zero-point error measured
// 0.007-0.031 s at a minute on clean streams (12.4): a fifty-fold margin.
var BEHIND_LIVE_SHOW_S = 2
// M4-04: the keyboard map. `?` IS THE ONE EXCEPTION to the bare-letter rule,
// and this comment used to say the opposite -- "LIST-MODE ONLY ... the footer
// never hints it in search mode" -- while Guide.qml's handleSearchKey had
// taken it from the day it was written. Both could not be true, and the one
// that was wrong was this one, so the footer and keyboardMap inherited a
// silence the code did not have.
//
// WHY THE EXCEPTION IS SOUND. DETAIL_KEY, PAUSE_KEY and TRACKS_KEY are bare
// printable characters and therefore list-mode only: in search mode they are
// query text and there is nothing to be done about it, which is why WALL_KEY
// had to take a modifier. `?` is different in one measurable way: tokenize
// drops it entirely, so a query of "?" alone has zero terms and filters
// nothing. The keystroke was already a no-op on the results and showed only
// as a stray character, so taking it for the map costs a user nothing -- and
// the guide OPENS in search mode, which is exactly the screen a first-time
// user needs the map from. The exception is NARROW: it holds only while the
// query is empty, so `who?` is unaffected.
//
// So all three places say so. handleSearchKey takes it on an empty query,
// footerHints' empty-query search line hints it last, and keyboardMap files
// it under both Channel list and Search because it is reached from both.
var HELP_KEY = "?"

var SOURCE_KEYS = { open: "o", add: "a", xtream: "c", edit: "e", remove: "x", logos: "g", reveal: "Ctrl+R", clear: "Ctrl+U", paste: "Ctrl+V" }
var SOURCE_KEY_RE = /^[0-9a-f]{8}(-[0-9]{1,3})?$/
var SOURCE_ORIGINS = ["guide", "xtream", "cli", "migrated"]
var URL_FIELDS = ["playlist", "epg"]
var FORM_LIMITS = { label: MAX_LABEL, playlist: MAX_SOURCE_URL, epg: MAX_SOURCE_URL, server: MAX_XTREAM_SERVER, username: MAX_XTREAM_FIELD, password: MAX_XTREAM_FIELD }
var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

// ---- input hygiene (ARCHITECTURE-SOURCES 3.1 / 6.1)

var CONTROL_RE = /[\u0000-\u001f\u007f-\u009f]/g

function capLength(text, limit) {
  var max = Number(limit) > 0 ? Math.floor(Number(limit)) : MAX_SOURCE_URL
  return text.length > max ? text.substring(0, max) : text
}

// Field boundary rule for a NAME (the label; the Xtream username and
// password; see sanitizeUrlInput for why not a URL): control characters
// (CR, LF, TAB, the C1 range) removed so a multi-line paste collapses to
// one line, ASCII space and NBSP trimmed, then capped at `limit` UTF-16
// units. Applied to every paste into such a field, on submit, and inside
// validateLabel and xtreamUrls.
function sanitizeInput(text, limit) {
  // SR15: a leading byte-order mark (a common paste artefact) is dropped.
  return capLength(trimEdgeSpace(str(text).replace(/^\ufeff/, "").replace(CONTROL_RE, "")), limit)
}

// Field boundary rule for a URL (D-SRC-63, R32a''', 2026-10-22): NOTHING
// inside the text is deleted. sanitizeInput used to serve URL fields too,
// and it rewrote them: `http://u:pa<TAB>ss@h.test/x` validated as the
// password `pass`, in both mirrors, and the user learned of it only as a
// wrong-password failure; `http://h.test/x<LF>http://evil.test/` validated
// as ONE url, `http://h.test/xhttp://evil.test/`, which nobody typed. A
// reader REFUSES whitespace (validateSourceUrl, the union class) and a
// control character, and it can only refuse what reaches it -- so a tab, a
// line break, an information separator or U+0085 inside a URL is kept here
// and refused there, with the one `invalid` sentence. What IS taken off:
// one leading byte-order mark (SR15, a paste artefact), and the six ASCII
// whitespace characters plus NBSP off both ENDS -- a trailing newline from
// `wl-copy`, a tab-indented line -- because a URL cannot end in one and the
// value the user meant is unambiguous. Then capped at `limit` UTF-16
// units. Applied to every paste into a URL field (Guide.qml through
// sanitizeFieldInput), on submit, inside validateSourceUrl, and on the CLI
// path (entryInputForm, reconcileSources). The helper's
// _sanitize_url_input is the mirror; the shared source-urls fixture holds
// both to it.
function sanitizeUrlInput(text, limit) {
  var s = str(text)
  if (s.charCodeAt(0) === 0xfeff) s = s.substring(1)
  var a = 0
  var b = s.length
  while (a < b && isUrlEdgeSpace(s.charCodeAt(a))) a++
  while (b > a && isUrlEdgeSpace(s.charCodeAt(b - 1))) b--
  return capLength(a === 0 && b === s.length ? s : s.substring(a, b), limit)
}

// The six ASCII whitespace characters (URL_DELIMITER_CODES) and NBSP.
function isUrlEdgeSpace(c) {
  return c === 0x20 || (c >= 0x09 && c <= 0x0d) || c === 0xa0
}

// Whether `text` holds a C0 control, DEL or a C1 control: what a URL reader
// refuses rather than deletes (D-SRC-63). `search`, not `test`: CONTROL_RE
// is global, and a global regex's `test` carries its lastIndex across calls.
function hasControlChar(text) {
  return str(text).search(CONTROL_RE) !== -1
}

// D-PERF-3 (R30g). ASCII space and NBSP off both ends, and nothing else --
// NOT String.prototype.trim, which takes every Unicode space and the line
// terminators, where this rule has only ever taken these two (SR15, and the
// helper's `strip(" \u00a0")`). It was `/^[ \u00a0]+|[ \u00a0]+$/g`, whose
// second half tries `+$` from every position of a run and backs out of the
// rest of it: quadratic in a run of spaces, and it ran BEFORE the cap, on a
// playlist's `url-tvg` hint (epgHintUrl) as on a paste. Two index walks now.
function trimEdgeSpace(text) {
  var s = str(text)
  var a = 0
  var b = s.length
  while (a < b && (s.charCodeAt(a) === 32 || s.charCodeAt(a) === 160)) a++
  while (b > a && (s.charCodeAt(b - 1) === 32 || s.charCodeAt(b - 1) === 160)) b--
  return a === 0 && b === s.length ? s : s.substring(a, b)
}

// Unicode code points, not UTF-16 units (SR22: the label cap counts code
// points in both languages).
function codePoints(text) {
  return Array.from(str(text))
}

function codePointLength(text) {
  return codePoints(text).length
}

function capCodePoints(text, limit) {
  var cps = codePoints(text)
  return cps.length > limit ? cps.slice(0, limit).join("") : str(text)
}

// While typing (UX-SOURCES 2.3): controls removed and capped, edges kept so
// a label can be typed with spaces; the trim happens on paste and submit.
function sanitizeTyping(text, limit) {
  return capLength(str(text).replace(CONTROL_RE, ""), limit)
}

function lowerFirst(text) {
  var t = str(text)
  return t === "" ? t : t.charAt(0).toLowerCase() + t.substring(1)
}

// User-facing sentence per result code (UX-SOURCES 5.4, numbers from
// LIMITS per SR5). Service / helper code names (`bad_url`, `bad_server`,
// ...) map onto the same sentences so any action result can be shown.
// `opts.field === "epg"` yields the `EPG: ...` variant; `opts.label` fills
// the duplicate / label_taken sentences.

// R33b / R33c: THE ONE SENTENCE for a value refused because of what is
// inside it, built the same way for a URL and for a name, so the Xtream
// fields' refusal (D-SRC-65) and the URL fields' are one rule with the
// noun swapped. `withSpace` names the space, which a URL refuses and a name
// does not. The sentence names what to remove, never the value.
function innerCharSentence(noun, withSpace) {
  return "Remove the " + (withSpace ? "space, " : "") + "tab, line break or control character inside the " + noun
}

function sourceErrorMessage(code, opts) {
  var o = opts || {}
  var c = str(code)
  var quoted = QUOTE_OPEN + str(o.label) + QUOTE_CLOSE
  var schemeText = "Start with http://, https://, or / for a local file"
  var invalidText = "Invalid URL" + SEP + "check the host"
  var serverText = "Server must start with http:// or https://"
  var table = {
    empty: "Enter a playlist URL or path",
    scheme: schemeText,
    unsupported_scheme: schemeText,
    invalid: invalidText,
    bad_url: invalidText,
    // R33b / R33c (round 7, 2026-10-22): the refusal for whitespace or a
    // control character INSIDE a value names it, in one sentence shape for
    // the three places that refuse rather than delete (D-SRC-63, D-SRC-65):
    // a URL (the playlist, the EPG, the Xtream server -- `url_control`,
    // carried by validateSourceUrl under the code `invalid`, so every
    // caller that switches on the code is unchanged) and the Xtream
    // username and password (`user_control`, `pass_control`, their own
    // codes like user_empty). A URL refuses a space as well; a name does not
    // (a username may hold one, encoded into the query), so the URL's
    // sentence names it and the names' do not.
    url_control: innerCharSentence("URL", true),
    user_control: innerCharSentence("username", false),
    pass_control: innerCharSentence("password", false),
    relative_path: "Use an absolute path (starts with /, not ~)",
    unsafe_path: "Path not allowed",
    too_long: "Too long" + SEP + "max " + formatCount(MAX_SOURCE_URL) + " characters",
    duplicate: str(o.label) !== "" ? "Already in Sources as " + quoted : "Already in Sources",
    label_too_long: "Label too long" + SEP + "max " + formatCount(MAX_LABEL) + " characters",
    label_taken: "A source named " + quoted + " already exists",
    server_empty: "Enter the server URL",
    server_scheme: serverText,
    bad_server: serverText,
    server_path: "Server is just http://host:port" + SEP + "no path",
    server_userinfo: "Server must not contain a username or password" + SEP + "enter them below",
    server_too_long: "Server too long" + SEP + "max " + formatCount(MAX_XTREAM_SERVER) + " characters",
    user_empty: "Enter the username",
    pass_empty: "Enter the password",
    bad_credentials: "Enter the username and password",
    user_too_long: "Username too long" + SEP + "max " + formatCount(MAX_XTREAM_FIELD) + " characters",
    pass_too_long: "Password too long" + SEP + "max " + formatCount(MAX_XTREAM_FIELD) + " characters",
    too_many: "Sources is full (" + formatCount(MAX_SOURCES) + ")" + SEP + "remove one first",
    busy: "Busy" + SEP + "wait for the current fetch to finish",
    unknown_source: "Source not found",
    not_ready: "Not ready yet" + SEP + "try again in a moment",
    persist_failed: "Could not save settings" + SEP + "try omarchy bar set",
    // R13 / SR25 as amended 2026-10-12: the state write is the switch, so a
    // state write that FAILED is the one failure a switch, a remove or an
    // adoption can have. Names the directory, never a URL, and never
    // `omarchy bar set` (which would put a credential in the shell history).
    state_write_failed: "Could not write state.json" + SEP + "check ~/.local/state/omarchy-iptv",
    // R22a (round 12): the no-write mode. A source call is refused rather
    // than made in memory only, because nothing made now would be kept.
    state_unreadable: "state.json could not be read" + SEP + "nothing is saved until it can be",
    // D-SINK-18. Deliberately NOT the persist_failed sentence: that one sends
    // the user to `omarchy bar set`, which would write the credentialed URL
    // into their shell history permanently -- the durable exposure engineering
    // rule 5 (dev branch) says is not accepted. This one names the real fix
    // instead, and the command it names carries no secret.
    // D-SINK-18, reworded after the review: the refusing verdicts are no
    // longer only "readable by other users". `absent` no longer refuses at
    // all, and what is left is a symlink, a device, someone else's file, a
    // file replaced mid-change, or a chmod that failed -- for which "is
    // readable by other users" is a misdiagnosis. "Could not be made
    // private" is true of every one of them and still names the fix for the
    // common one.
    config_unsafe: "Settings file could not be made private" + SEP + "chmod 600 ~/.config/omarchy/shell.json",
    cancelled: "Cancelled"
  }
  var text = table[c] || ""
  if (text === "") return c === "" || c === "ok" ? "" : "Could not save the source (" + c + ")"
  if (o.field === "epg") return "EPG: " + lowerFirst(text)
  return text
}

// Older name from the architecture: same sentences.
function sourceReason(code) {
  return sourceErrorMessage(code)
}

// Every reason Service.sourcesPersistFailed can carry (SR25 as amended
// 2026-10-12). The guide renders the sentence for THE reason it was given:
// `state_write_failed` names the state directory, `config_unsafe` names the
// chmod, and only `persist_failed` -- a host entry updateEntryInline could
// not rewrite -- says `omarchy bar set`, because that write carries no
// credential. An unknown reason falls back to persist_failed's sentence. The
// round-4 review's P2: the guide rendered persist_failed's copy for every
// reason, so a failed write in ~/.local/state told the user to put the URL
// into their shell history, the durable sink rule 5 forbids advising.
var PERSIST_FAILURE_REASONS = ["state_write_failed", "config_unsafe", "persist_failed"]

function persistFailureMessage(reason) {
  var r = str(reason)
  if (PERSIST_FAILURE_REASONS.indexOf(r) === -1) r = "persist_failed"
  return sourceErrorMessage(r)
}

// D-SINK-19 round 13, R23f. What a refusal the guide shows SAYS. In the
// no-write mode (`blocked`, Service.stateWriteBlocked: the reason, "" when
// writes are allowed) every refusal says the no-write reason, whatever the
// call answered: the round-12 live lens turned logos on in that mode and
// was told "Could not save settings - try omarchy bar set" -- the wrong
// reason and the wrong advice, because the guide mapped every `false` to
// persist_failed. Otherwise the sentence for the code: `kind` "persist"
// reads it as a sourcesPersistFailed reason (persistFailureMessage), any
// other kind as a result code (sourceErrorMessage).
function refusalMessage(code, blocked, kind) {
  if (str(blocked) !== "") return sourceErrorMessage("state_unreadable")
  return kind === "persist" ? persistFailureMessage(code) : sourceErrorMessage(code)
}

// ---- URL validation (ARCHITECTURE-SOURCES 3.1 with the UX 5.4 codes, SR6)
//
// Accepted: absolute paths, `file://` URLs (normalized to the path) and
// `http(s)://` URLs with a host. The normalized `url` is the source's
// identity: scheme and host lowercased, numeric port normalized (leading
// zeros stripped, the scheme default dropped), empty path `/`, query
// verbatim (provider tokens are case-sensitive), fragment dropped, userinfo
// kept. `./` and `../` paths are refused (`relative_path`, UX 5.4); `~`
// paths are refused from the forms and accepted verbatim from the CLI
// (`opts.origin === "cli"`, SR11); `/proc`, `/sys`, `/dev` are refused
// (`unsafe_path`, SR13). Text without a scheme is `scheme` when it looks
// like a host and `relative_path` otherwise (SR12). The authority refuses
// backslashes, zero-width characters, ports above 65535 and bracket
// literals that are not IPv6 (SR15). `opts.kind === "epg"` makes an empty
// value ok (the EPG is optional) and prefixes the messages with `EPG:`.
var ZERO_WIDTH_RE = /[\u200b-\u200d\u2060\ufeff]/
// D-PERF-3 (R30g). An IPv6 literal is `[`, hex digits, `:` and `.` with at
// least one `:`, an optional `%25` zone, and `]`. The pattern used to say
// "at least one colon" as `[...]*:[...]*`, two runs over one class around a
// literal that class also matches, which backtracks quadratically over a
// run of colons before a failing tail; on a playlist's `url-tvg` hint that
// is provider text. The class run is now one run and the colon is asked for
// with indexOf (isIpv6Literal), which is the same set of strings.
var IPV6_LITERAL_RE = /^\[([0-9A-Fa-f:.]*)(?:%25[A-Za-z0-9._~-]+)?\]$/
function isIpv6Literal(text) {
  var m = IPV6_LITERAL_RE.exec(str(text))
  return m !== null && m[1].indexOf(":") !== -1
}

// D-PERF-3 (R30g). `text.replace(/[?#].*$/, "")`, which is what the file
// branch below did, without the regex: `.` stops at a line terminator and `$`
// is the end of the text, so the match was the first `?` or `#` AFTER the
// last line terminator -- and finding it by retrying `.*$` from every `?` or
// `#` before one was quadratic. Two index walks give the same cut.
function cutQueryAndFragment(text) {
  var s = str(text)
  var from = 0
  for (var i = s.length - 1; i >= 0; i--) {
    var c = s.charCodeAt(i)
    if (c === 10 || c === 13 || c === 0x2028 || c === 0x2029) { from = i + 1; break }
  }
  for (var j = from; j < s.length; j++) {
    var d = s.charCodeAt(j)
    if (d === 63 || d === 35) return s.substring(0, j)
  }
  return s
}

// D-SINK-25 / D-SINK-27, ruling R32a (2026-10-21). A URL's authority ends at
// the first `/`, `?` or `#` after `//` and its userinfo at the LAST `@`
// WITHIN that authority (D-SINK-1 kept); an `@` after the authority is path
// or query, never a credential marker. So `http://user:2024/ab@host.test/x`
// -- a password holding an unencoded `/` -- READS as host `user`, port 2024,
// in both mirrors, and is accepted, resolved, normalized and labelled that
// way, because that is what the string says and every standard parser
// agrees. The round-2 rule that refused it (`passwordReadAsPort`, lane
// bounds-s) is WITHDRAWN: it also refused an Xtream
// `/playlist/<email>/<pass>/m3u_plus` link and a WebDAV link on a
// non-default port, both stored and working, and the helper dropped them on
// the next normalize after the upgrade (D-SINK-27). No URL is refused for an
// `@` after its authority, in either mirror. What the form does instead is
// WARN (sourceUrlWarning, below), once, and never refuse.
//
// Where the ambiguity is told: the Sources form warns when the RFC host has
// no dot and an `@` follows later in the URL -- a bare-word "host" that is
// most likely a username, followed by what is most likely the real host --
// and says how to encode the three characters that end an authority (`/` as
// %2F, `?` as %3F, `#` as %23). A bracketed literal and a dotted name are
// hosts and draw no warning; `http://nas:8000/files/me@home/x` warns too,
// which is the warning's cost: a sentence, not a refusal.
//
// R32a' (D-SINK-29, 2026-10-22): that question -- "is this dotless RFC host
// a username, with the real host after a later `@`?" -- is ONE predicate,
// `urlHostWithheld`, computed from the typed text and independently of
// validation, and it has three customers: the form's warning below (a value
// that validates), the form's `invalid` error (a value that does not: the
// `#` typo reads as port `pa` and is refused, and the refusal now carries
// the encoding sentence, so the user who typed the ruling's own example is
// told how to fix it), and the FREE-TEXT redactors (`redactUrls`, the
// helper's `redact_urls`), which WITHHOLD the host when it holds rather
// than print the username (D-SINK-28) or cross the `/` to the next `@`
// (D-SINK-29, a password tail). The helper mirrors it as `host_withheld`.
var ENCODE_SENTENCE = "If a password holds /, ? or #, write them as %2F, %3F and %23."
var WARN_AT_AFTER_AUTHORITY = "The host before the first / has no dot and an @ follows it. " + ENCODE_SENTENCE
// The token a free-text redactor prints in place of a withheld host. Owned
// here; the helper's HOST_WITHHELD is its mirror and the shared redaction
// fixture holds both to it.
var HOST_WITHHELD = "[host withheld]"

// R32a'. The RFC authority of the text after one `scheme://` and what a
// free-text redactor prints for it: `host` is what follows the authority's
// LAST `@` (D-SINK-1: the userinfo ends there), cut at the authority's end
// (the first `/`, `?`, `#` or whitespace) and at the first `:` (a port),
// `;`, `=` or `&` (a parameter delimiter, so a neighbouring parameter never
// prints, D-SINK-23); a bracketed literal is the host up to its `]`, or
// nothing. `withheld` is the predicate, two arms (R32a'', 2026-10-22), each
// needing an `@` after the authority before whitespace: the host is not
// bracketed and has no dot (D-SINK-28: `http://myuser:pa#ss@cdn.test/x`
// reads as host `myuser`, port `pa`); OR the authority carries a NON-NUMERIC
// port -- a `:` after its last `@` whose text, up to the next `;`, `=` or
// `&`, is non-empty and not all digits (D-SINK-35:
// `http://user.name:pa/ss@h.test/x` reads as host `user.name`, port `pa`,
// which is a dotted username and a password; `http://me@mail.test:pa/ss@h.test/x`
// the same). What remains, stated: a dotted username before a digits-only
// password prefix (`http://user.name:2024/ab@host/x` prints `user.name`)
// reads as host and port and nothing here can tell. An EMPTY port
// (`http://user:/ab@h.test/x`) validates as an RFC shape and does not count
// as non-numeric; a bracketed literal is never withheld. The authority ends
// at the six ASCII delimiters (urlDelimiterIndex, R32a''': the same six
// that end the run) and at no other whitespace: a password holding U+FEFF
// or NBSP is URL text, and its host prints (D-SINK-36). Where that cut is
// observable, stated so nobody adds a test that mirrors the code (the
// recheck of lane-bounds-s4 found two mutations here surviving by
// composition). Through redactUrls, REMOVING the cut changes nothing: the
// run handed in was already cut at the same six. Cutting at a WIDER class
// than the run's does show through it: a run holding U+FEFF would end its
// authority there and print the username, which is D-SINK-32's shape and
// is pinned by the shared vectors. And through urlHostWithheld over form
// or CLI text, since D-SRC-63 (sanitizeUrlInput keeps a tab), removing the
// cut shows too: `http://my:pa<TAB>/ss@h.test/x` ends its authority at
// the tab, before the `/`, so the later `@` is not seen and the refusal
// carries no encoding sentence; without the cut it would. The shared
// source-urls fixture pins that shape in both mirrors (measured: each
// mutation goes red, 2026-10-22).
// Every scan is one index walk or one single-class search; nothing here is
// retried. The helper's `run_host_parts` is the mirror.
function runHostParts(body) {
  var s = str(body)
  var sp = urlDelimiterIndex(s)
  if (sp !== -1) s = s.substring(0, sp)
  var cut = s.search(/[\/?#]/)
  var authority = cut === -1 ? s : s.substring(0, cut)
  var rest = cut === -1 ? "" : s.substring(cut)
  var hostport = authority.substring(authority.lastIndexOf("@") + 1)
  if (hostport.charAt(0) === "[") {
    var close = hostport.indexOf("]")
    return { host: close === -1 ? "" : hostport.substring(0, close + 1), withheld: false }
  }
  var end = hostport.search(/[:;=&]/)
  var host = end === -1 ? hostport : hostport.substring(0, end)
  var port = ""
  if (end !== -1 && hostport.charAt(end) === ":") {
    port = hostport.substring(end + 1)
    var portEnd = port.search(/[;=&]/)
    if (portEnd !== -1) port = port.substring(0, portEnd)
  }
  var laterAt = rest.indexOf("@") !== -1
  var dotless = host !== "" && host.indexOf(".") === -1
  var badPort = port !== "" && !/^[0-9]+$/.test(port)
  return { host: host, withheld: laterAt && (dotless || badPort) }
}

// R32a': the predicate alone, over a whole URL (or any text holding one).
function urlHostWithheld(text) {
  var s = str(text)
  var j = s.indexOf("://")
  return j !== -1 && runHostParts(s.substring(j + 3)).withheld
}

// The form's warning for a value that VALIDATES as http(s): the predicate
// over the TYPED text, not the normalized URL (validateSourceUrl drops the
// fragment, and `http://user:2024#ab@host.test` is the `#` typo). A value
// that does not validate draws the error line instead, and that line
// carries the encoding sentence when the predicate holds (validateSourceUrl).
function sourceUrlWarning(text) {
  var v = validateSourceUrl(text)
  if (!v.ok || v.kind !== "http") return ""
  return urlHostWithheld(sanitizeUrlInput(text, MAX_SOURCE_URL + 1)) ? WARN_AT_AFTER_AUTHORITY : ""
}

// The form's warning line: the first URL field (playlist, EPG, Xtream server)
// whose value draws sourceUrlWarning, or "". Advice beside the result line,
// shown while the field holds such a value (UX-SOURCES 5.4); submit proceeds.
function formWarningLine(form) {
  if (!form || typeof form !== "object" || !form.values || typeof form.values !== "object") return ""
  var fields = form.kind === "xtream" ? ["server"] : ["playlist", "epg"]
  for (var i = 0; i < fields.length; i++) {
    var w = sourceUrlWarning(form.values[fields[i]])
    if (w !== "") return w
  }
  return ""
}

// SR12: a "." or ":" before the first "/" reads as a host.
function looksLikeHost(text) {
  return /[.:]/.test(str(text).split("/")[0])
}

function validateSourceUrl(text, opts) {
  var o = opts || {}
  var field = o.kind === "epg" ? "epg" : "playlist"
  var cli = o.origin === "cli"
  function fail(code) {
    return { ok: false, code: code, message: sourceErrorMessage(code, { field: field }), field: field, kind: "", url: "", host: "" }
  }
  function pass(kind, url, host) {
    return { ok: true, code: "ok", message: "", field: field, kind: kind, url: url, host: host }
  }
  // R33b (round 7, 2026-10-22): a refusal for whitespace or a control
  // character INSIDE the value keeps the code `invalid` (every caller that
  // switches on the code, D16's status and the shared fixture among them,
  // is unchanged) and carries the sentence that names it (`url_control`):
  // "check the host" sent the user to the wrong place for a tab in a
  // password or a line break inside a wrapped URL.
  function innerChar() {
    var r = fail("invalid")
    r.message = sourceErrorMessage("url_control", { field: field })
    return r
  }
  function filePath(path) {
    // D-SRC-63: a decoded `file:` path may carry what the raw text did not
    // (`file:///a%09b`); a control character in a path is refused here as
    // it is below, because the state readers (parseState, the helper's
    // normalize_state) drop a record whose url holds one.
    if (hasControlChar(path)) return innerChar()
    if (/^\/(proc|sys|dev)(\/|$)/.test(path)) return fail("unsafe_path")
    return pass("file", path, "")
  }
  // D-SRC-63 (R32a'''): the URL boundary rule deletes nothing inside the
  // text, so what sanitizeInput used to rewrite is refused below instead.
  var s = sanitizeUrlInput(text, MAX_SOURCE_URL + 1)
  // R32a': an `invalid` refusal of a value that reads as a dotless host with
  // a later `@` -- `http://myuser:pa#ss@cdn.test/x`, port `pa` -- says how
  // to encode the password, so the typo the warning exists for is told on
  // the error line that wins over it (the recheck's P2 on lane-bounds-s2).
  function invalid() {
    var r = fail("invalid")
    if (urlHostWithheld(s)) r.message = r.message + ". " + ENCODE_SENTENCE
    return r
  }
  if (s === "") return field === "epg" ? pass("", "", "") : fail("empty")
  if (s.length > MAX_SOURCE_URL) return fail("too_long")
  // D-SRC-63: a control character anywhere -- a tab, a line break, an
  // information separator, U+0085, a NUL -- in a path, a file URL or an
  // http URL is REFUSED, never deleted (sanitizeInput deleted it, and
  // `http://u:pa<TAB>ss@h.test/x` validated as the password `pass`). Both
  // state readers drop a record whose url holds one, so accepting it would
  // store a source the next load discards. The helper's validate_source_url
  // refuses the same text. R33b: told by the sentence that names it.
  if (hasControlChar(s)) return innerChar()
  if (s.indexOf("//") === 0) return fail("scheme")
  if (s.charAt(0) === "/") return filePath(s)
  if (s.charAt(0) === "~") return cli ? pass("file", s, "") : fail("relative_path")
  if (s === "." || s === ".." || s.indexOf("./") === 0 || s.indexOf("../") === 0) return fail("relative_path")
  // [\s\S] rather than `.`: a line separator (U+2028 / U+2029) inside an
  // http URL is whitespace (`invalid`), not a missing scheme (D-SRC-06).
  var m = s.match(/^([A-Za-z][A-Za-z0-9+.-]*):([\s\S]*)$/)
  if (!m) return fail(looksLikeHost(s) ? "scheme" : "relative_path")
  var scheme = m[1].toLowerCase()
  var rest = m[2]
  if (scheme === "file") {
    if (rest.indexOf("//") !== 0) return invalid()
    var after = cutQueryAndFragment(rest.substring(2))
    var slash = after.indexOf("/")
    if (slash === -1) return invalid()
    var decoded
    try { decoded = decodeURIComponent(after.substring(slash)) } catch (e) { return invalid() }
    if (decoded.charAt(0) !== "/") return invalid()
    return filePath(decoded)
  }
  if (scheme !== "http" && scheme !== "https") return fail("scheme")
  if (rest.indexOf("//") !== 0) return invalid()
  // R32a''': a READER refuses the union class (URL_SPACE_CODES: JS `\s`,
  // Python `\s` and U+FEFF together), where a redactor delimits at the six
  // ASCII characters only. Since D-SRC-63 every member reaches this line
  // (sanitizeUrlInput deletes nothing inside the text; the control members
  // were already refused above), so a tab in a password is `invalid` here
  // and not the password `pass`.
  if (urlSpaceIndex(rest) !== -1) return innerChar()
  var body = rest.substring(2)
  var cut = body.search(/[\/?#]/)
  var authority = cut === -1 ? body : body.substring(0, cut)
  var tail = cut === -1 ? "" : body.substring(cut)
  if (authority.indexOf("\\") !== -1 || ZERO_WIDTH_RE.test(authority)) return invalid()
  var userinfo = ""
  var hostport = authority
  var at = authority.lastIndexOf("@")
  if (at !== -1) {
    userinfo = authority.substring(0, at)
    hostport = authority.substring(at + 1)
  }
  var host = ""
  var port = ""
  if (hostport.charAt(0) === "[") {
    var close = hostport.indexOf("]")
    if (close === -1) return invalid()
    host = hostport.substring(0, close + 1)
    if (!isIpv6Literal(host)) return invalid()
    var afterHost = hostport.substring(close + 1)
    if (afterHost !== "") {
      if (afterHost.charAt(0) !== ":") return invalid()
      port = afterHost.substring(1)
    }
  } else {
    var colon = hostport.lastIndexOf(":")
    host = colon === -1 ? hostport : hostport.substring(0, colon)
    port = colon === -1 ? "" : hostport.substring(colon + 1)
    if (/[:\[\]]/.test(host)) return invalid()
  }
  if (host === "") return invalid()
  host = host.toLowerCase()
  if (port !== "") {
    if (!/^[0-9]+$/.test(port)) return invalid()
    port = port.replace(/^0+(?=[0-9])/, "")
    if (Number(port) > 65535) return invalid()
  }
  if ((scheme === "http" && port === "80") || (scheme === "https" && port === "443")) port = ""
  var hash = tail.indexOf("#")
  if (hash !== -1) tail = tail.substring(0, hash)
  var q = tail.indexOf("?")
  var path = q === -1 ? tail : tail.substring(0, q)
  var query = q === -1 ? "" : tail.substring(q + 1)
  if (path === "") path = "/"
  var url = scheme + "://" + (userinfo !== "" ? userinfo + "@" : "") + host + (port !== "" ? ":" + port : "") + path + (query !== "" ? "?" + query : "")
  return pass("http", url, host)
}

// Normalized identity of an accepted URL, "" when it does not validate.
// `opts` reaches validateSourceUrl (the settings path passes origin `cli`).
function normalizeSourceUrl(text, opts) {
  var v = validateSourceUrl(text, opts)
  return v.ok ? v.url : ""
}

// ---- the guide URL the playlist declares (M4-01 repair 3, D-EPG-2)
//
// `#EXTM3U url-tvg="..."` / `x-tvg-url="..."` has reached channels.json as
// `epgUrlHint` since the helper's first playlist parser and NOTHING
// has ever read it. A provider that tells us where its guide lives was
// ignored, and the owner's own install carries no guide URL at all -- so the
// one repair of the four that can fix an install without the user typing
// anything was sitting in the cache unused.
//
// Two decisions, both deliberate.
//
// 1. THE HINT IS RESOLVED AT FETCH TIME AND NEVER PERSISTED. It is not
//    written into the source record (`epgUrl`) and not into the bar settings.
//    A playlist's declaration belongs to the playlist: copying it into the
//    user's own field would destroy the only fact that lets the two be told
//    apart, so the user could neither recognise it as the provider's nor get
//    rid of it -- clearing the field would re-adopt the same value on the next
//    refresh, which reads as the plugin refusing to forget a URL. Resolution
//    is a pure function of (the user's URL, the cache's hint): typing a URL
//    buries the hint, clearing the field reveals it again, and there is
//    nothing to migrate in either direction.
// 2. A HINTED URL IS PROVIDER-CONTROLLED INPUT. It goes through the same
//    validateSourceUrl a typed one does, and then through a NARROWER scheme
//    rule: only `http`/`https` survive. validateSourceUrl accepts absolute
//    paths and `file://` for a TYPED value, because a user may keep a guide
//    on disk; honouring either from a playlist would let a remote party
//    choose which local file this plugin opens and parses. A user's own file
//    guide is unaffected -- it is typed, not hinted.
//
// Both halves of the resolution are redacted to scheme and host at every
// sink the same way the user's URL is: nothing here returns a URL to the
// guide. `host` is the redacted form callers display; `url` is for the fetch
// environment only (D-SINK-8).
var EPG_ORIGIN_NONE = ""
var EPG_ORIGIN_USER = "user"
var EPG_ORIGIN_PLAYLIST = "playlist"

// The channels.json hint, validated and narrowed to http(s), or "".
function epgHintUrl(meta) {
  var m = meta && typeof meta === "object" ? meta : {}
  var raw = str(m.epgUrlHint)
  if (raw === "") return ""
  var v = validateSourceUrl(raw, { kind: "epg" })
  // `kind: "epg"` passes an EMPTY value as ok with kind "", so `v.ok` alone
  // would accept nonsense that sanitized away to nothing; and `kind !==
  // "http"` is decision 2 above, not a formality -- that branch is the one
  // that refuses `/etc/passwd` and `file:///...` from a provider.
  if (!v.ok || v.kind !== "http" || v.url === "") return ""
  return v.url
}

// Which guide URL is in force, and where it came from.
//
// The user's own value always wins, and an INVALID user value still wins: it
// is returned verbatim with origin `user` so the helper reports the fault the
// user can see and fix. Substituting the provider's hint for a URL the user
// mistyped would produce an error message about a URL they never entered, or
// worse, silently fetch somewhere else and look like it worked.
function resolveEpgUrl(opts) {
  var o = opts || {}
  var user = str(o.userUrl)
  if (user !== "") return { url: user, origin: EPG_ORIGIN_USER, host: hostOf(user), fromPlaylist: false }
  var hint = epgHintUrl({ epgUrlHint: o.hint })
  if (hint === "") return { url: "", origin: EPG_ORIGIN_NONE, host: "", fromPlaylist: false }
  return { url: hint, origin: EPG_ORIGIN_PLAYLIST, host: hostOf(hint), fromPlaylist: true }
}

// The one line of copy that makes the provenance visible (M4-01 repair 3:
// "saying in Sources where it came from"). "" for a URL the user typed and
// for none at all -- a typed URL needs no provenance, it is theirs.
var EPG_HINT_NOTICE = "Guide URL from the playlist"

function epgOriginNotice(origin) {
  return str(origin) === EPG_ORIGIN_PLAYLIST ? EPG_HINT_NOTICE : ""
}

function isUrlField(field) {
  return URL_FIELDS.indexOf(str(field)) !== -1
}

// ---- keys and lookups (ARCHITECTURE-SOURCES 3.2, D4)

function sourceKey(url) {
  return fnv1a32(url)
}

function isSourceKey(key) {
  return SOURCE_KEY_RE.test(str(key))
}

function findSource(sources, key) {
  var k = str(key)
  if (k === "") return null
  var list = asList(sources)
  for (var i = 0; i < list.length; i++) if (list[i] && str(list[i].key) === k) return list[i]
  return null
}

function findSourceByUrl(sources, url) {
  var u = str(url)
  if (u === "") return null
  var list = asList(sources)
  for (var i = 0; i < list.length; i++) if (list[i] && str(list[i].url) === u) return list[i]
  return null
}

// The record with this url keeps its key; otherwise fnv1a32(url), suffixed
// `-2`, `-3`, ... while another record already uses it (harmless collision).
function allocateSourceKey(sources, url) {
  var existing = findSourceByUrl(sources, url)
  if (existing) return str(existing.key)
  var base = sourceKey(url)
  var key = base
  for (var n = 2; findSource(sources, key) !== null; n++) key = base + "-" + n
  return key
}

// `<cacheDir>/sources/<key>`; "" when either input is empty or the key is
// not a key (the helper validates again before it touches the path).
function sourceCacheDir(cacheDir, key) {
  var dir = str(cacheDir).replace(/\/+$/, "")
  if (dir === "" || !isSourceKey(key)) return ""
  return dir + "/" + SOURCES_DIR + "/" + str(key)
}

// ---- labels (UX-SOURCES 5.6)

// D-SINK-17. The userinfo ends at the LAST `@` in the authority, not the first,
// and this took the first: `[^@/?#]*@` cannot cross an at-sign, so
// `https://user:p@ss@host.example/list.m3u` gave `ss@host.example` and
// `https://u@er:pass@host.example/list.m3u` gave `er:pass@host.example` -- the
// whole password, in the Sources row's host and its default label, on a source
// whose URL is masked everywhere else. Raised by the marketplace maintainer
// against the shipped 0.13.1; the username case is worse than the report and
// was found by measuring it.
//
// This is D-SINK-1 exactly, one function along: that was `redactUrls` leaking
// the password tail when the password contained an at-sign, and its repair was
// to cut at the LAST at-sign rather than the first. `validateSourceUrl` does
// that over a properly isolated authority (bounded by `/`, `?` and `#`) and is
// the model for the shape below.
//
// Do NOT read that as "the neighbours are all already safe", which an earlier
// version of this comment implied and a review refuted by calling them.
// `redactUrls` and `sourceLabel` bounded the userinfo scan at `/` and
// whitespace only, never at `?` or `#`, so on a URL with no path an at-sign
// in the QUERY was taken as the delimiter. This comment then said they "never
// UNDER-redact -- whatever they emit starts after an at-sign". That was
// FALSE, and the example it rested on, `http://h.test?a=b@c` -> `c`, had
// nothing after the at-sign to show it: `http://h.test?u=me@b.test&p=SECRET`
// gave `b.test&p=SECRET`, the password with it (D-SINK-23, the bounds sweep's
// sinks review). Both now end the authority at the first `/`, `?` or `#`, as
// this function and validateSourceUrl do, and the helper's urllib does; the
// shared redaction fixture holds the JavaScript and the Python to it.
//
// R32a (D-SINK-27): the RFC host, exactly as validateSourceUrl reads it --
// the authority up to the first `/`, `?` or `#`, after its last `@`. The
// round-2 reading that showed the host after a LATER at-sign is withdrawn:
// it put an email username's domain on the Sources row of an Xtream
// `/playlist/<email>/<pass>/m3u_plus` link. The form's warning
// (sourceUrlWarning) is where the typo shape is told.
function hostPortOf(url) {
  var m = str(url).match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]*)/i)
  if (!m) return ""
  var authority = m[1]
  var at = authority.lastIndexOf("@")
  var hostport = at === -1 ? authority : authority.substring(at + 1)
  return hostport.toLowerCase()
}

// Default label: the host (lowercase, leading `www.` dropped, `:port` kept
// when present) for URLs and the Xtream server; the file name for paths.
function deriveLabel(url, kind) {
  var text = str(url)
  var k = str(kind)
  var v = validateSourceUrl(text, { origin: "cli" })
  if (k === "file" || v.kind === "file") {
    var path = v.ok ? v.url : text
    var name = path.replace(/\/+$/, "").split("/").pop()
    return capCodePoints(sanitizeInput(name), MAX_LABEL) || "local file"
  }
  var hostport = hostPortOf(v.ok ? v.url : text)
  if (hostport === "") return capCodePoints(sanitizeInput(text), MAX_LABEL)
  return capCodePoints(sanitizeInput(hostport.replace(/^www\./, "")), MAX_LABEL)
}

function labelKey(text) {
  return sanitizeInput(text).toLowerCase()
}

// `existing` is a list of labels or of records / views ({ label, id | key }).
// `selfId` excludes the record being edited.
function labelTaken(label, existing, selfId) {
  var want = labelKey(label)
  if (want === "") return false
  var list = asList(existing)
  var self = str(selfId)
  for (var i = 0; i < list.length; i++) {
    var item = list[i]
    if (item === null || item === undefined) continue
    var key, id
    if (typeof item === "object") {
      key = labelKey(item.label)
      id = str(item.id !== undefined ? item.id : item.key)
    } else {
      key = labelKey(item)
      id = ""
    }
    if (self !== "" && id === self) continue
    if (key === want) return true
  }
  return false
}

// Appends ` 2`, ` 3`, ... while the label is taken (case-insensitive);
// derived labels only, a typed label is rejected with `label_taken` instead.
function uniqueLabel(label, existing, selfId) {
  var base = capCodePoints(sanitizeInput(label), MAX_LABEL)
  if (base === "") base = "source"
  if (!labelTaken(base, existing, selfId)) return base
  for (var n = 2; n < 1000; n++) {
    var suffix = " " + n
    var candidate = capCodePoints(base, MAX_LABEL - suffix.length) + suffix
    if (!labelTaken(candidate, existing, selfId)) return candidate
  }
  return base
}

// Architecture name: derived + unique in one call.
function defaultSourceLabel(url, kind, existingLabels) {
  return uniqueLabel(deriveLabel(url, kind), existingLabels)
}

// SR22: the cap counts code points; over-cap labels are refused, never cut.
function validateLabel(label, existing, selfId) {
  var text = sanitizeInput(label)
  if (codePointLength(text) > MAX_LABEL) return { ok: false, code: "label_too_long", field: "label", message: sourceErrorMessage("label_too_long"), label: text }
  if (labelTaken(text, existing, selfId)) return { ok: false, code: "label_taken", field: "label", message: sourceErrorMessage("label_taken", { label: text }), label: text }
  return { ok: true, code: "ok", field: "", message: "", label: text }
}

// ---- masking (SR4, UX-SOURCES 4.4)

function maskQuery(query) {
  var parts = str(query).split("&")
  var out = []
  for (var i = 0; i < parts.length; i++) {
    var part = parts[i]
    var eq = part.indexOf("=")
    if (eq === -1) { out.push(part); continue }
    var name = part.substring(0, eq)
    out.push(MASK_CLEAR_PARAMS.indexOf(name.toLowerCase()) !== -1 ? part : name + "=" + MASK)
  }
  return out.join("&")
}

// Fixed token `****` for the userinfo, every query value (except `type` and
// `output`, never secrets) and the fragment; scheme, host, port, path and
// query keys stay. Paths and anything that is not a URL come back unchanged,
// so `maskUrl(v) === v` means "nothing to mask" (no eye button, Ctrl+R no-op).
//
// D-PERF-11 (R30g, 2026-10-22). This was one pattern,
// `^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^\/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$`,
// whose second and third groups are two unbounded runs over OVERLAPPING
// classes with nothing between them that the first could not take: when the
// tail failed -- and it fails exactly when a line terminator follows the
// `#`, because `.` stops there and `$` is the end of the text -- the engine
// retried every split of the authority and the path, about k*k/2 steps for
// k characters of user text. The three index walks below are the same
// parse: the authority ends at the first `/`, `?` or `#`, the path at the
// first `?` or `#`, the query at the first `#`, and a fragment holding a line
// terminator is the one shape the old pattern did not match, so that text
// comes back unchanged as it always did. Held equal to the old pattern by
// an oracle in the node suite (dev branch) over the fixtures and seeded
// ordinary URLs with line breaks before and after a `#`.
function maskUrl(url) {
  var text = str(url)
  var m = text.match(/^([A-Za-z][A-Za-z0-9+.-]*):\/\//)
  if (!m) return text
  if (m[1].toLowerCase() === "file") return text
  var body = text.substring(m[0].length)
  var hash = body.indexOf("#")
  if (hash !== -1 && /[\n\r\u2028\u2029]/.test(body.substring(hash))) return text
  var cut = body.search(/[\/?#]/)
  var authority = cut === -1 ? body : body.substring(0, cut)
  var rest = cut === -1 ? "" : body.substring(cut)
  var at = authority.lastIndexOf("@")
  if (at !== -1) authority = MASK + "@" + authority.substring(at + 1)
  var q = rest.search(/[?#]/)
  var path = q === -1 ? rest : rest.substring(0, q)
  var after = q === -1 ? "" : rest.substring(q)
  var query = ""
  if (after.charAt(0) === "?") {
    var h = after.indexOf("#")
    query = "?" + maskQuery((h === -1 ? after : after.substring(0, h)).substring(1))
    after = h === -1 ? "" : after.substring(h)
  }
  var fragment = after.charAt(0) === "#" ? "#" + MASK : ""
  return m[1] + "://" + authority + path + query + fragment
}

// ---- Xtream Codes (ARCHITECTURE-SOURCES 3.4 / D10, UX-SOURCES 1.8, 5.4)

// RFC 3986 unreserved set only (A-Za-z0-9-._~), identical to Python
// quote(v, safe="") so node, the Qt engine and the helper agree.
function encodeQueryValue(value) {
  return encodeURIComponent(str(value)).replace(/[!'()*]/g, function(ch) {
    return "%" + ch.charCodeAt(0).toString(16).toUpperCase()
  })
}

// Builds the get.php / xmltv.php URLs from server, username and password.
// Accepts positional arguments or one object. The server must carry its
// scheme (no guessing, UX 8 #9) and nothing after host[:port] (UX 8 #10);
// a trailing slash is tolerated. Codes are the UX 5.4 Xtream set.
function xtreamUrls(server, username, password) {
  var o = server !== null && typeof server === "object" ? server : { server: server, username: username, password: password }
  function fail(code, field) {
    return { ok: false, code: code, field: field, message: sourceErrorMessage(code), playlistUrl: "", epgUrl: "", host: "", base: "" }
  }
  // D-SRC-63: the server is a URL, so nothing inside it is deleted; a
  // control character or whitespace inside it is refused by the validator
  // below. The username and password used to stay on sanitizeInput, which
  // deleted a control character into a different credential; since
  // D-SRC-65 (R33c) they refuse it first (below). The paste path strips it
  // for a name field (sanitizeFieldInput) and a Qt TextInput never delivers
  // one from a key, so the refusal is reached by the service call shape
  // (Service.buildXtreamSource, a caller handing values straight in).
  var srv = sanitizeUrlInput(o.server, MAX_XTREAM_SERVER + 1)
  if (srv === "") return fail("server_empty", "server")
  if (srv.length > MAX_XTREAM_SERVER) return fail("server_too_long", "server")
  if (!/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(srv)) return fail("server_scheme", "server")
  var v = validateSourceUrl(srv)
  if (!v.ok) {
    if (v.code === "scheme") return fail("server_scheme", "server")
    // R32a': the validator's own `invalid` sentence, which carries the
    // encoding advice when the server reads as a dotless host with a later
    // `@` (`http://myuser:pa#ss@cdn.test`); the same text otherwise.
    var bad = fail("invalid", "server")
    bad.message = v.message
    return bad
  }
  if (v.kind !== "http") return fail("server_scheme", "server")
  var m = v.url.match(/^(https?:\/\/[^\/?#@]+)\/?$/)
  // The validator drops a fragment from the normalized URL; on a server it
  // is refused like a path or a query (ARCH 3.4, D-SRC-08).
  if (!m || srv.indexOf("#") !== -1) {
    // SR17: credentials belong in the fields below, never in the server URL.
    var authorityEnd = v.url.indexOf("/", 8)
    var hasUserinfo = v.url.indexOf("@") !== -1 && (authorityEnd === -1 || v.url.indexOf("@") < authorityEnd)
    return fail(hasUserinfo ? "server_userinfo" : "server_path", "server")
  }
  var base = m[1]
  // D-SRC-65 (R33c, round 7, 2026-10-22): the username and password REFUSE
  // a control character rather than delete it -- the URL rule one layer
  // down. sanitizeInput ran first and deleted it, so `pa<TAB>ss` reached
  // the provider as `pass`, encoded into the query, and the user learned
  // of it as a wrong-password failure: D-SRC-63's shape in the two fields
  // it left on the name rule. Refused BEFORE the name rule trims and caps,
  // on the raw value, so a control character at either edge is refused
  // too; the sentence is the URL refusal's, with the noun swapped
  // (innerCharSentence). A space inside stays allowed and encoded.
  if (hasControlChar(o.username)) return fail("user_control", "username")
  var user = sanitizeInput(o.username, MAX_XTREAM_FIELD + 1)
  if (user === "") return fail("user_empty", "username")
  if (user.length > MAX_XTREAM_FIELD) return fail("user_too_long", "username")
  if (hasControlChar(o.password)) return fail("pass_control", "password")
  var pass = sanitizeInput(o.password, MAX_XTREAM_FIELD + 1)
  if (pass === "") return fail("pass_empty", "password")
  if (pass.length > MAX_XTREAM_FIELD) return fail("pass_too_long", "password")
  var creds = "username=" + encodeQueryValue(user) + "&password=" + encodeQueryValue(pass)
  return {
    ok: true, code: "ok", field: "", message: "",
    playlistUrl: base + "/get.php?" + creds + "&type=m3u_plus&output=ts",
    epgUrl: base + "/xmltv.php?" + creds,
    host: v.host,
    base: base
  }
}

// UX 8.1 name: `{ ok, code, field, message }` (plus the built URLs on ok).
function validateXtream(fields) {
  return xtreamUrls(fields || {})
}

// ---- view objects (SR1, UX-SOURCES 5.2, 7.1)

function pluralGroups(n) {
  var v = Math.floor(Number(n) || 0)
  return formatCount(v) + (v === 1 ? " group" : " groups")
}

// `1,475 channels in 28 groups`
function countsLine(channelCount, groupCount) {
  return pluralChannels(channelCount) + " in " + pluralGroups(groupCount)
}

function sameDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
}

// `used 21:30` (today), `used yesterday`, `used 3 Sep` (this year), `used 3
// Sep 2025` (older), `never used` (0). Local time, 24-hour clock.
function formatLastUsed(atSec, nowSec) {
  var at = Number(atSec) || 0
  if (at <= 0) return "never used"
  var d = new Date(at * 1000)
  var now = Number(nowSec) > 0 ? new Date(Number(nowSec) * 1000) : new Date()
  if (sameDay(d, now)) return "used " + formatClock(at)
  var yesterday = new Date(now.getTime())
  yesterday.setDate(yesterday.getDate() - 1)
  if (sameDay(d, yesterday)) return "used yesterday"
  var text = "used " + d.getDate() + " " + MONTHS[d.getMonth()]
  if (d.getFullYear() !== now.getFullYear()) text += " " + d.getFullYear()
  return text
}

// Architecture wording, kept for callers that want an interval.
function formatAgo(nowSec, atSec) {
  var at = Number(atSec) || 0
  if (at <= 0) return ""
  var diff = Math.max(0, Math.floor((Number(nowSec) || 0) - at))
  if (diff < 60) return "just now"
  if (diff < 3600) return Math.floor(diff / 60) + " min ago"
  if (diff < 86400) return Math.floor(diff / 3600) + " h ago"
  return Math.floor(diff / 86400) + " d ago"
}

// One state record -> the view object the guide binds (SR1). `kind` is the
// UX kind (`url` | `file` | `xtream`), `host` never a URL, `channelCount`
// -1 until the first successful fetch. `errorReason` is the session-only
// probe failure (already redacted) the service may attach.
// `epgFromPlaylist` (M4-01 repair 3) is the ACTIVE source's resolved hint:
// the hint lives in a source's own channels.json, and only the active
// source's cache is in memory, so no other row can know and none of them
// claims to. A source with its own `epgUrl` is never marked hinted -- the
// user's value wins in resolveEpgUrl and it must win here too, or the row
// would tell the user their own URL came from the provider.
function sourceView(source, activeKey, nowSec, errorReason, epgFromPlaylist) {
  var s = source || {}
  var key = str(s.key)
  var kind = str(s.kind) === "file" ? "file" : (str(s.origin) === "xtream" ? "xtream" : "url")
  var fetched = Number(s.fetchedAt) > 0
  var ownEpg = str(s.epgUrl) !== ""
  var hinted = !ownEpg && epgFromPlaylist === true && key !== "" && key === str(activeKey)
  return {
    id: key,
    label: str(s.label),
    kind: kind,
    host: kind === "file" ? "local file" : hostPortOf(s.url),
    hasEpg: ownEpg || hinted,
    epgFromPlaylist: hinted,
    channelCount: fetched ? Math.max(0, Math.floor(Number(s.channelCount) || 0)) : -1,
    groupCount: fetched ? Math.max(0, Math.floor(Number(s.groupCount) || 0)) : 0,
    cachedAt: fetched ? Math.floor(Number(s.fetchedAt)) : 0,
    lastUsedAt: Math.max(0, Math.floor(Number(s.lastUsed) || 0)),
    lastUsedText: formatLastUsed(s.lastUsed, nowSec),
    active: key !== "" && key === str(activeKey),
    origin: str(s.origin),
    errorReason: str(errorReason)
  }
}

// Every record as a view, active first, then last used (newest first),
// then added (newest first). `errors` is the service's { key: reason } map.
function sourceViews(state, activeKey, nowSec, errors, epgFromPlaylist) {
  var st = state || emptyState()
  var errs = errors && typeof errors === "object" ? errors : {}
  var list = asList(st.sources)
  var out = []
  for (var i = 0; i < list.length; i++) {
    if (!list[i]) continue
    var view = sourceView(list[i], activeKey, nowSec, errs[str(list[i].key)], epgFromPlaylist)
    view.addedAt = Math.floor(Number(list[i].addedAt) || 0)
    out.push(view)
  }
  // SR32: active first, then last used (newest first), then the never-used
  // records in the order they were added.
  out.sort(function(a, b) {
    if (a.active !== b.active) return a.active ? -1 : 1
    var au = a.lastUsedAt > 0
    var bu = b.lastUsedAt > 0
    if (au !== bu) return au ? -1 : 1
    if (au && a.lastUsedAt !== b.lastUsedAt) return b.lastUsedAt - a.lastUsedAt
    if (a.addedAt !== b.addedAt) return au ? b.addedAt - a.addedAt : a.addedAt - b.addedAt
    return a.label < b.label ? -1 : (a.label > b.label ? 1 : 0)
  })
  for (var j = 0; j < out.length; j++) delete out[j].addedAt
  return out
}

// Architecture name.
function sourceRows(state, activeKey, nowSec, errors, epgFromPlaylist) {
  return sourceViews(state, activeKey, nowSec, errors, epgFromPlaylist)
}

// The Sources row and accessible-name word for a hinted guide URL. One
// literal, two sinks, so the screen and the screen reader cannot drift.
var EPG_HINT_ROW_TEXT = "EPG from playlist"

// Row detail (UX-SOURCES 5.2): `active` (active source only), `used ...` on
// narrow cards, host, `Xtream`, counts or `not loaded yet`, `EPG`. Rows
// never carry error text (SR26); a failed retry's reason goes to the
// form's result line.
function sourceDetail(view, narrow) {
  var v = view || {}
  var parts = []
  if (v.active) parts.push("active")
  if (narrow) parts.push(str(v.lastUsedText) || formatLastUsed(v.lastUsedAt))
  parts.push(str(v.host))
  if (v.kind === "xtream") parts.push("Xtream")
  parts.push(Number(v.channelCount) >= 0 ? countsLine(v.channelCount, v.groupCount) : "not loaded yet")
  // M4-01 repair 3: `EPG` for a URL the user set, `EPG from playlist` for one
  // the playlist declared. The row is where the user finds out, and the two
  // must never read the same -- an adopted hint that looked like their own
  // setting is the failure this wording exists to prevent.
  if (v.hasEpg) parts.push(v.epgFromPlaylist === true ? EPG_HINT_ROW_TEXT : "EPG")
  return joinParts(parts)
}

// UX-SOURCES 7.1 row name.
function sourceAccessibleName(view) {
  var v = view || {}
  var out = str(v.label) + ", " + str(v.host)
  out += ", " + (Number(v.channelCount) >= 0 ? countsLine(v.channelCount, v.groupCount) : "not loaded yet")
  if (v.active) out += ", active"
  if (v.hasEpg) out += ", " + (v.epgFromPlaylist === true ? EPG_HINT_ROW_TEXT : "EPG")
  var used = str(v.lastUsedText) || formatLastUsed(v.lastUsedAt)
  out += ", " + (used === "never used" ? used : "last " + used)
  return out
}

// Header right slot: `3 sources`, `1 source`, `No sources`.
function sourcesHeaderCount(n) {
  var v = Math.floor(Number(n) || 0)
  if (v <= 0) return "No sources"
  return formatCount(v) + (v === 1 ? " source" : " sources")
}

// R24f (D-SRC-28). The Sources header's right slot: in the no-write mode it
// is the R23e notice's TITLE (one source of copy: Model.stateUnreadableNotice,
// the notification's and the guide body's own words), never "No sources" over
// a file that holds records nobody could read; otherwise the count.
// D-SRC-38 (round 15): `midSession` -- the mode began after a state loaded --
// says that saving has stopped instead (Model.stateBlockedHeader), because the
// rows under it were loaded and still play.
function sourcesHeaderRight(n, stateBlocked, path, midSession) {
  if (str(stateBlocked) !== "") return stateBlockedHeader(stateBlocked, path, midSession === true)
  return sourcesHeaderCount(n)
}

// Pinned column row name (UX-SOURCES 7.1).
function sourcesRowAccessibleName(n) {
  return "Sources, " + formatCount(n) + " saved"
}

// M2-04 / ruling rule 6. The message the logo switch is thrown against.
//
// Turning it ON is a disclosure to hosts the user did not choose, so it is
// confirmed and the confirmation states the count. Turning it OFF discloses
// nothing and is not confirmed at all: a dialog in front of the safe
// direction teaches people to dismiss dialogs.
function confirmLogosMessage(survey) {
  return logoConsentLines(survey).join("\n")
}

// Confirm dialog message (UX-SOURCES 5.7).
function confirmRemoveMessage(label, active) {
  var quoted = QUOTE_OPEN + str(label) + QUOTE_CLOSE
  if (active) return "Remove " + quoted + "? It is the active source; the guide returns to setup."
  return "Remove " + quoted + "? Its cache is deleted too."
}

// Result-line strings (UX-SOURCES 5.5). Hosts only, never a URL.
function fetchingLine(host, kind) {
  if (kind === "file") return "Reading the file" + ELLIPSIS
  return "Fetching from " + str(host) + ELLIPSIS
}

// R28e (2026-10-20): `code`, when the result carries one, names a refusal
// the plugin made ITSELF at the commit -- Sources full (R27c), the no-write
// mode, a record gone -- which is about this machine, not the host, so the
// line does not say "from <host>": round 1's review read "Sources is full
// (50) \u00b7 remove one first from 127.0.0.1". A failure the fetch reported
// (no code) keeps the host, as UX-SOURCES 5.5 has it.
var PROBE_LOCAL_REFUSALS = ["too_many", "state_unreadable", "unknown_source"]
function probeFailureLine(reason, host, kind, code) {
  var text = redactUrls(str(reason)) || "Unknown error"
  if (kind === "file" || str(host) === "" || PROBE_LOCAL_REFUSALS.indexOf(str(code)) !== -1) return text
  return text + " from " + str(host)
}

// Footer transients (UX-SOURCES 5.3). `added` names the new source by its
// label (`Added list.m3u`, `Added tv.example.net`), never `local file`;
// `host` is the fallback when the caller has no label.
function sourceTransient(event, opts) {
  var o = opts || {}
  var counts = Number(o.channelCount) >= 0 ? countsLine(o.channelCount, o.groupCount) : ""
  if (event === "loaded") return counts
  if (event === "added") return "Added " + (str(o.label) !== "" ? str(o.label) : str(o.host)) + (counts !== "" ? SEP + counts : "")
  if (event === "saved") return "Saved" + (counts !== "" ? SEP + counts : "")
  if (event === "switched") return "Switched to " + str(o.label) + (Number(o.channelCount) >= 0 ? SEP + pluralChannels(o.channelCount) : "")
  if (event === "removed") return "Removed " + str(o.label) + (o.wasActive ? SEP + "no active source" : "")
  return ""
}

// The paste path (D-CLIP-1, R8). The shell never holds more than the
// bounded reply: the helper's `clipboard` verb runs wl-paste with a pipe,
// reads at most CLIPBOARD_MAX_BYTES, terminates the child at the cap, EOF
// or its deadline, and prints one JSON object. The first fix collected
// wl-paste's whole output in the shell and cut it afterwards -- measured, a
// user Ctrl+V over a 100 MB foreign offer cost the shell +298 MB and kept
// most of it; the bound was time, not bytes.
//
// The arithmetic, mirrored by MAX_CLIPBOARD_* in the helper (bin/helper/) and
// pinned on both sides by the shared clipboard fixture: the shell keeps
// LIMITS.url * 4 = 8192 UTF-16 units; a UTF-8 character is at most 4
// bytes, so 32768 bytes (32 KiB) is the most a reply can need. The helper's
// deadline is CLIPBOARD_TIMEOUT_MS; the shell's watchdog (Service.qml
// clipboardWatchdog) is the OUTER bound and sits beyond the helper's
// deadline plus TWO kill graces (a SIGTERM wait and then a SIGKILL wait, the
// helper's reap_child) plus a second of interpreter start-up, so a helper
// that answers "timeout" on time is read rather than killed mid-reply, and a helper that cannot answer at
// all is still killed. A producer that drips bytes at the protocol's 1 s
// per-read timeout runs into the helper's deadline; the bound kills a
// CHILD, never the shell.
var CLIPBOARD_TIMEOUT_MS = 5 * 1000
var CLIPBOARD_KILL_GRACE_MS = 1000
var CLIPBOARD_WATCHDOG_MS = CLIPBOARD_TIMEOUT_MS + 2 * CLIPBOARD_KILL_GRACE_MS + 2000
var CLIPBOARD_MAX_CHARS = MAX_SOURCE_URL * 4
var CLIPBOARD_MAX_BYTES = CLIPBOARD_MAX_CHARS * 4
export {
  CACHE_LAYOUT, MAX_SOURCES, MAX_SOURCE_URL, MAX_LABEL, MAX_XTREAM_SERVER,
  MAX_XTREAM_FIELD, SOURCES_DIR, MASK, MASK_CLEAR_PARAMS, LIMITS, PAUSE_KEY,
  TRACKS_KEY, DETAIL_KEY, REWIND_KEY, FORWARD_KEY, LIVE_KEY, REWIND_STEP_S,
  BEHIND_LIVE_SHOW_S, HELP_KEY, SOURCE_KEYS, SOURCE_KEY_RE, SOURCE_ORIGINS,
  URL_FIELDS, FORM_LIMITS, MONTHS, CONTROL_RE, capLength, sanitizeInput,
  sanitizeUrlInput, isUrlEdgeSpace, hasControlChar, trimEdgeSpace, codePoints,
  codePointLength, capCodePoints, sanitizeTyping, lowerFirst,
  innerCharSentence, sourceErrorMessage, sourceReason,
  PERSIST_FAILURE_REASONS, persistFailureMessage, refusalMessage,
  ZERO_WIDTH_RE, IPV6_LITERAL_RE, isIpv6Literal, cutQueryAndFragment,
  ENCODE_SENTENCE, WARN_AT_AFTER_AUTHORITY, HOST_WITHHELD, runHostParts,
  urlHostWithheld, sourceUrlWarning, formWarningLine, looksLikeHost,
  validateSourceUrl, normalizeSourceUrl, EPG_ORIGIN_NONE, EPG_ORIGIN_USER,
  EPG_ORIGIN_PLAYLIST, epgHintUrl, resolveEpgUrl, EPG_HINT_NOTICE,
  epgOriginNotice, isUrlField, sourceKey, isSourceKey, findSource,
  findSourceByUrl, allocateSourceKey, sourceCacheDir, hostPortOf, deriveLabel,
  labelKey, labelTaken, uniqueLabel, defaultSourceLabel, validateLabel,
  maskQuery, maskUrl, encodeQueryValue, xtreamUrls, validateXtream,
  pluralGroups, countsLine, sameDay, formatLastUsed, formatAgo, sourceView,
  sourceViews, sourceRows, EPG_HINT_ROW_TEXT, sourceDetail,
  sourceAccessibleName, sourcesHeaderCount, sourcesHeaderRight,
  sourcesRowAccessibleName, confirmLogosMessage, confirmRemoveMessage,
  fetchingLine, PROBE_LOCAL_REFUSALS, probeFailureLine, sourceTransient,
  CLIPBOARD_TIMEOUT_MS, CLIPBOARD_KILL_GRACE_MS, CLIPBOARD_WATCHDOG_MS,
  CLIPBOARD_MAX_CHARS, CLIPBOARD_MAX_BYTES
}
